import unittest

from robot_pet import RobotPet


def make_pet():
    """Create a RobotPet, whatever arguments its constructor happens to take."""
    for args in (("Robo", "Dog"), ("Robo",), (), ("Robo", "Dog", 100)):
        try:
            return RobotPet(*args)
        except TypeError:
            continue
    return RobotPet.__new__(RobotPet)


with open("unit_tests_that_change_state.py") as source_file:
    printed_tests = source_file.read()

class_source = (
    "class TestRobotPet(unittest.TestCase):\n"
    "    def setUp(self):\n"
    "        self.pet = make_pet()\n\n" + printed_tests
)

namespace = {"unittest": unittest, "make_pet": make_pet}
exec(class_source, namespace)
TestRobotPet = namespace["TestRobotPet"]

if __name__ == "__main__":
    unittest.main(argv=["run_tests.py"], verbosity=2)
